SELECT FROM `t_supporting_facilities` f WHERE COALESCE(f.`delFlag`, '0') = '0' AND f.`crzdbh` = #{crzdbh}
AND f.`ptxmmc` LIKE CONCAT('%', #{keyword}, '%')
ORDER BY f.`ptxmmc` LIMIT #{limit}

SELECT * FROM `t_supporting_facilities`
WHERE COALESCE(`delFlag`, '0') = '0' AND `ptxmmc` = #{ptxmmc}
LIMIT 1
